@msig trait AtomicResultPublisher_supervision_atomicResultPublisher_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher)
  }

  /** helper function to set the values of all input ports.
   * @param candidatePlan payload for data port candidatePlan
   * @param arbitrationStatus payload for data port arbitrationStatus
   * @param recoveryReport payload for data port recoveryReport
   */
  def put_concrete_inputs(candidatePlan : HVAC_Visibility_Priority_Supervisor.CandidatePlan,
                          arbitrationStatus : HVAC_Visibility_Priority_Supervisor.ArbitrationStatus,
                          recoveryReport : HVAC_Visibility_Priority_Supervisor.RecoveryReport): Unit = {
    put_candidatePlan(candidatePlan)
    put_arbitrationStatus(arbitrationStatus)
    put_recoveryReport(recoveryReport)
  }


  /** helper function to check AtomicResultPublisher_supervision_atomicResultPublisher's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param actuationPlan method that will be called with the value of the outgoing data
   *        port 'actuationPlan'.
   * @param supervisorStatus method that will be called with the value of the outgoing data
   *        port 'supervisorStatus'.
   */
  def check_concrete_output(actuationPlan: HVAC_Visibility_Priority_Supervisor.CabinActuationPlan => B,
                            supervisorStatus: HVAC_Visibility_Priority_Supervisor.SupervisorStatus => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val actuationPlanValue: HVAC_Visibility_Priority_Supervisor.CabinActuationPlan = get_actuationPlan().get
    if(!actuationPlan(actuationPlanValue)) {
      testFailures = testFailures :+ st"'actuationPlan' did not match expected: value of the outgoing data port is ${actuationPlanValue}"
    }
    val supervisorStatusValue: HVAC_Visibility_Priority_Supervisor.SupervisorStatus = get_supervisorStatus().get
    if(!supervisorStatus(supervisorStatusValue)) {
      testFailures = testFailures :+ st"'supervisorStatus' did not match expected: value of the outgoing data port is ${supervisorStatusValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_candidatePlan(value : HVAC_Visibility_Priority_Supervisor.CandidatePlan): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher.operational_api.candidatePlan_Id, HVAC_Visibility_Priority_Supervisor.CandidatePlan_Payload(value))
  }

  // setter for in DataPort
  def put_arbitrationStatus(value : HVAC_Visibility_Priority_Supervisor.ArbitrationStatus): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher.operational_api.arbitrationStatus_Id, HVAC_Visibility_Priority_Supervisor.ArbitrationStatus_Payload(value))
  }

  // setter for in DataPort
  def put_recoveryReport(value : HVAC_Visibility_Priority_Supervisor.RecoveryReport): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher.operational_api.recoveryReport_Id, HVAC_Visibility_Priority_Supervisor.RecoveryReport_Payload(value))
  }

  // getter for out DataPort
  def get_actuationPlan(): Option[HVAC_Visibility_Priority_Supervisor.CabinActuationPlan] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.CabinActuationPlan] = get_actuationPlan_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.CabinActuationPlan_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port actuationPlan.  Expecting 'HVAC_Visibility_Priority_Supervisor.CabinActuationPlan_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.CabinActuationPlan]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_actuationPlan_payload(): Option[HVAC_Visibility_Priority_Supervisor.CabinActuationPlan_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher.initialization_api.actuationPlan_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.CabinActuationPlan_Payload]]
  }

  // getter for out DataPort
  def get_supervisorStatus(): Option[HVAC_Visibility_Priority_Supervisor.SupervisorStatus] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.SupervisorStatus] = get_supervisorStatus_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.SupervisorStatus_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port supervisorStatus.  Expecting 'HVAC_Visibility_Priority_Supervisor.SupervisorStatus_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.SupervisorStatus]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_supervisorStatus_payload(): Option[HVAC_Visibility_Priority_Supervisor.SupervisorStatus_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_atomicResultPublisher.initialization_api.supervisorStatus_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.SupervisorStatus_Payload]]
  }

}
